	/**
	 * AJAX handler to render an app inline using a shortcode or custom action.
	 */
	public function ajax_render_app() {
		check_ajax_referer( 'arc_portal_render_app', 'nonce' );

		if ( ! is_user_logged_in() || ! ->has_allowed_role() ) {
			wp_send_json_error( array( 'message' => __( 'No tienes permisos.', 'arc-portal' ) ) );
		}

		 = isset( ['app'] ) ? sanitize_key( wp_unslash( ['app'] ) ) : '';
		     = ->get_app(  );

		if ( !  || empty( ['target'] ) ) {
			wp_send_json_error( array( 'message' => __( 'App no encontrada.', 'arc-portal' ) ) );
		}

		if ( 'shortcode' === ['target'] && ! empty( ['shortcode'] ) ) {
			 = do_shortcode( '[' . sanitize_text_field( ['shortcode'] ) . ']' );
			wp_send_json_success( array( 'html' =>  ) );
		}

		if ( 'ajax' === ['target'] ) {
			ob_start();
			/**
			 * Fires when an app with target 'ajax' is requested.
			 *
			 * @param array  App configuration.
			 */
			do_action( 'arc_portal_app_ajax_content',  );
			 = ob_get_clean();
			wp_send_json_success( array( 'html' =>  ?  : '<p>' . esc_html__( 'No hay contenido configurado para esta app.', 'arc-portal' ) . '</p>' ) );
		}

		wp_send_json_error( array( 'message' => __( 'Target no soportado.', 'arc-portal' ) ) );
	}
